body {
  background-color: #f5f6f8;
  color: #18181b;
  font-family: system-ui, "Segoe UI", sans-serif;
  line-height: 1.6;
  padding: 16px;
}

h1 { font-size: 32px; margin-bottom: 8px; }
h1 a { color: inherit; text-decoration: none; }

.nav {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 12px 0;
  margin-bottom: 16px;
  border-bottom: 1px solid #e4e4e7;
}

.nav a {
  color: #3f3f46;
  text-decoration: none;
  padding: 4px 2px;
}

.nav a[aria-current="page"] {
  color: #1d4ed8;
  font-weight: 600;
  border-bottom: 2px solid #1d4ed8;
}

.cart-count {
  margin-left: auto;
  background-color: #2563eb;
  color: #ffffff;
  border-radius: 999px;
  padding: 2px 10px;
}

.product-grid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 16px;
}

@media (min-width: 768px) {
  .product-grid { grid-template-columns: 1fr 1fr 1fr; }
}

.product-card,
.product-detail,
.cart,
.not-found {
  background-color: #ffffff;
  padding: 16px;
  border-radius: 10px;
}

.product-card h3 a {
  color: #18181b;
  text-decoration: none;
}

.product-card h3 a:hover { text-decoration: underline; }

.price { color: #3f3f46; }

.btn-add {
  background-color: #2563eb;
  color: #ffffff;
  padding: 10px 16px;
  border: none;
  border-radius: 6px;
  cursor: pointer;
  font-size: 15px;
}

.cart ul {
  list-style: none;
  padding: 0;
}

.cart li {
  padding: 6px 0;
  border-bottom: 1px solid #e4e4e7;
}

.cart-total {
  font-size: 20px;
  font-weight: 700;
  text-align: right;
}

import React, { useState, useEffect } from "react";
import { createRoot } from "react-dom/client";

const STORAGE_KEY = "shopmn-cart";

const products = [
  { id: 1, name: "Монгол дээл", price: 129000, description: "Хонин ноосон дулаан дээл." },
  { id: 2, name: "Малгай", price: 45000, description: "Уламжлалт хээтэй өвлийн малгай." },
  { id: 3, name: "Гутал", price: 89000, description: "Арьсан монгол гутал." },
];

function formatPrice(value) {
  return "₮ " + value.toLocaleString("en-US");
}

function loadCart() {
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY));
    return Array.isArray(saved) ? saved : [];
  } catch (error) {
    return [];
  }
}

function currentRoute() {
  return window.location.hash.replace(/^#/, "") || "/";
}

function useHashRoute() {
  const [route, setRoute] = useState(currentRoute);

  useEffect(() => {
    function handleHashChange() {
      setRoute(currentRoute());
    }

    window.addEventListener("hashchange", handleHashChange);
    return () => window.removeEventListener("hashchange", handleHashChange);
  }, []);

  return route;
}

function useCart() {
  const [cart, setCart] = useState(loadCart);

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(cart));
  }, [cart]);

  function addToCart(product) {
    setCart((prev) => {
      const existing = prev.find((item) => item.id === product.id);
      if (existing) {
        return prev.map((item) =>
          item.id === product.id ? { ...item, quantity: item.quantity + 1 } : item
        );
      }
      return [...prev, { ...product, quantity: 1 }];
    });
  }

  const count = cart.reduce((sum, item) => sum + item.quantity, 0);
  const totalPrice = cart.reduce((sum, item) => sum + item.price * item.quantity, 0);

  return { cart, addToCart, count, totalPrice };
}

function ProductCard({ product, onAdd }) {
  return (
    <article className="product-card">
      <h3>
        <a href={"#/product/" + product.id} data-testid="product-link">{product.name}</a>
      </h3>
      <p className="price">{formatPrice(product.price)}</p>
      <button className="btn-add" data-testid="add-to-cart" onClick={() => onAdd(product)}>
        Сагсанд хийх
      </button>
    </article>
  );
}

function Nav({ route, count }) {
  return (
    <nav className="nav">
      <a
        href="#/"
        data-testid="nav-home"
        aria-current={route === "/" ? "page" : undefined}
      >
        Нүүр
      </a>
      <a
        href="#/cart"
        data-testid="nav-cart"
        aria-current={route === "/cart" ? "page" : undefined}
      >
        Сагс
      </a>
      <span className="cart-count" data-testid="cart-count">{count}</span>
    </nav>
  );
}

function HomePage({ onAdd }) {
  return (
    <section className="product-grid" data-testid="home">
      {products.map((product) => (
        <ProductCard key={product.id} product={product} onAdd={onAdd} />
      ))}
    </section>
  );
}

function CartPage({ cart, totalPrice }) {
  return (
    <section className="cart" data-testid="cart-page">
      <h2>Таны сагс</h2>
      {cart.length === 0 ? (
        <p data-testid="cart-empty">Сагс хоосон байна.</p>
      ) : (
        <ul data-testid="cart-items">
          {cart.map((item) => (
            <li key={item.id}>
              {item.name} × {item.quantity}
            </li>
          ))}
        </ul>
      )}
      <p className="cart-total" data-testid="cart-total">{formatPrice(totalPrice)}</p>
    </section>
  );
}

function ProductPage({ id, onAdd }) {
  const product = products.find((item) => item.id === id);

  if (!product) {
    return <NotFoundPage />;
  }

  return (
    <section className="product-detail" data-testid="product-page">
      <h2 data-testid="detail-name">{product.name}</h2>
      <p className="price" data-testid="detail-price">{formatPrice(product.price)}</p>
      <p>{product.description}</p>
      <button className="btn-add" data-testid="add-to-cart" onClick={() => onAdd(product)}>
        Сагсанд хийх
      </button>
    </section>
  );
}

function NotFoundPage() {
  return (
    <section className="not-found" data-testid="not-found">
      <h2>Хуудас олдсонгүй</h2>
      <p>Хайсан хуудас чинь байхгүй байна.</p>
      <a href="#/">Нүүр хуудас руу буцах</a>
    </section>
  );
}

function App() {
  const { cart, addToCart, count, totalPrice } = useCart();
  const route = useHashRoute();

  return (
    <main>
      <h1>
        <a href="#/">Shop.mn</a>
      </h1>
      <Nav route={route} count={count} />
      {route === "/cart" ? (
        <CartPage cart={cart} totalPrice={totalPrice} />
      ) : (
        <HomePage onAdd={addToCart} />
      )}
    </main>
  );
}

createRoot(document.getElementById("root")).render(<App />);

